  export const CALL_BOOKED_TEXT: string | null = "Your Peabudy ID call: {{call_time}}\n\nHi {{first_name}}, your video ID call with our team is on:\n\n{{call_time}}\n\nHow to join: {{call_link}}\n\n- About 10 minutes, on video, with one person from our team.\n- Have a photo ID ready: a passport, driver's licence or national ID card. You must be 18 or over.\n- We look at your ID and check it matches you. We don't record the call or keep a copy of your ID.\n\nNeed a different time? Reply to this email.\n\nThe call is free. We'll never ask you for money, card details or passwords on the call or anywhere else.\n\nPeabudy never asks for money. Never pay an 'agent fee', 'inspection fee' or deposit before you've seen a home in person and confirmed who the landlord is.\n\n--\nPeabudy · [POSTAL ADDRESS]\nYou're getting this because you applied to join Peabudy with this email address.\n";
  